diff --git a/src/main/kotlin/parcel/api/CheckoutEndpoint.kt b/src/main/kotlin/parcel/api/CheckoutEndpoint.kt
index 6c1729c..84fbd5d 100644
--- a/src/main/kotlin/parcel/api/CheckoutEndpoint.kt
+++ b/src/main/kotlin/parcel/api/CheckoutEndpoint.kt
@@ -11,12 +11,23 @@ data class CheckoutRequest(
     val basket: Basket,
     val destination: DeliveryZone,
     val mode: String = "home",
+    val lockerId: String? = null,
+    val lockerZone: DeliveryZone? = null,
 )

 class CheckoutEndpoint(private val pricing: Pricing) {
     fun quote(request: CheckoutRequest): QuoteResult =
         when (request.mode) {
             "home" -> pricing.quote(request.basket, request.destination, DeliveryOption.Home)
+            "locker" -> {
+                val lockerId = request.lockerId
+                val lockerZone = request.lockerZone
+                if (lockerId.isNullOrBlank() || lockerZone == null) {
+                    QuoteResult.Unavailable(QuoteFailure.MISSING_LOCKER)
+                } else {
+                    pricing.quote(request.basket, request.destination, DeliveryOption.Locker(lockerId, lockerZone))
+                }
+            }
             else -> QuoteResult.Unavailable(QuoteFailure.UNSUPPORTED_MODE)
         }
 }
